ruleContent.content:
@js:
var html = result;
var m = html.match(/d\("([A-Za-z0-9+\\/]+=*)",\s*"(b[0-9a-f]+)"\)\)/);
if (m) {
  var enc = m[1].replace(/\\\//g, '/');
  var key = m[2];
  var md5 = java.md5Encode(key);
  var iv = md5.substring(0, 16);
  var aesKey = md5.substring(16);
  var decrypted = java.aesBase64DecodeToString(enc, aesKey, 'AES/CBC/PKCS7Padding', iv);
  result = decrypted || org.jsoup.Jsoup.parse(html).select('#RBGsectionThree-content').html();
} else {
  result = org.jsoup.Jsoup.parse(html).select('#RBGsectionThree-content').html();
}

ruleToc.chapterList:
@js:
var html = result;
var list = [];
var re = /data-kiki="([^"]+)"[\s\S]*?data-bubu="([^"]+)"/g;
var m;
while ((m = re.exec(html)) !== null) {
  var name = m[1];
  var bubu = m[2];
  try {
    var url = java.base64Decode(bubu);
    if (url.indexOf('http') != 0) {
      url = 'https://www7.long4book.com' + url;
    }
    list.push({name: name, url: url});
  } catch(e) {}
}
result = list;
